(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-982":{scenario:{company:"Viện Chính sách Đô thị An Hòa",supervisor:{name:"Vũ Thanh Hà",role:{vi:"Trưởng nhóm Đánh giá tác động chính sách",en:"Head of Regulatory Impact Assessment"}},ref_code:"RIA-2611",title:{vi:"Tách khoản chuyển giao. Chiết khấu đúng. Báo cáo trung thực.",en:"Net out transfers. Discount correctly. Report honestly."},brief:{vi:"Đây là tình huống đào tạo. Thành phố đề xuất chính sách hỗ trợ đổi xe máy xăng cũ sang xe điện. Năm 0: chi phí triển khai 60 tỷ đồng và tiền trợ giá trả cho hộ dân 240 tỷ đồng. Lợi ích ròng kinh tế (đã trừ chi phí mua xe) 85 tỷ đồng/năm trong năm 1-4. Bản nháp RIA-2611 xếp tiền trợ giá vào COST và báo NPV 40 tỷ đồng. Đối chiếu hướng dẫn phân tích đã duyệt, sửa hai trường và lập báo cáo có căn cứ.",en:"This is a training scenario. The city proposes a policy to help households swap old petrol motorbikes for electric ones. Year 0: implementation cost 60 billion VND and subsidies paid to households 240 billion VND. Economic net benefits (after vehicle purchase costs) are 85 billion VND per year in years 1-4. Draft RIA-2611 books the subsidy as COST and reports an NPV of 40 billion VND. Compare it with the approved guidance, correct both fields and write an evidence-based report."},reference_title:{vi:"Hướng dẫn phân tích chi phí - lợi ích đã duyệt · RIA-2611",en:"Approved cost-benefit analysis guidance · RIA-2611"},fields:[{id:"SUBSIDY_CLS",label:{vi:"Phân loại tiền trợ giá trong CBA",en:"Subsidy classification in the CBA"},initial:"COST",expected:"TRANSFER",choices:["COST","BENEFIT","TRANSFER"],reference:"Hướng dẫn phân loại dòng tiền CBA",hint:{vi:"Ngân sách chi ra đúng bằng số hộ dân nhận được: xã hội không tiêu hao nguồn lực thật nào.",en:"The budget pays out exactly what households receive: society uses up no real resources."}},{id:"NPV_BN",label:{vi:"NPV kinh tế (tỷ đồng)",en:"Economic NPV (billion VND)"},initial:"40",expected:"209",reference:"Bảng chiết khấu dòng lợi ích",ref_value:{vi:"Chi phí kinh tế năm 0 không gồm khoản chuyển giao; lợi ích 85 tỷ/năm, năm 1-4; suất chiết khấu mô phỏng 10%",en:"Year-0 economic cost excludes transfers; benefits 85 billion per year in years 1-4; training discount rate 10%"},hint:{vi:"Bản nháp cộng thẳng lợi ích các năm; lợi ích năm t phải chia cho (1 + r) mũ t.",en:"The draft simply adds yearly benefits; the benefit in year t must be divided by (1 + r) to the power t."}}],sop32:{vi:"NPV = -C0 + Σ Bt/(1+r)^t với t = 1-4; C0 chỉ gồm chi phí nguồn lực thật, loại khoản chuyển giao (trợ giá, thuế); r = 10% (mô phỏng); làm tròn đến số nguyên tỷ đồng.",en:"NPV = -C0 + Σ Bt/(1+r)^t for t = 1-4; C0 covers only real resource costs and excludes transfers (subsidies, taxes); r = 10% (training); round to the nearest billion VND."},context:{label:"RIA / RIA-2611",metrics:[{label:{vi:"Chi phí triển khai năm 0",en:"Year-0 implementation cost"},value:"60,000,000,000 VND"},{label:{vi:"Trợ giá cho hộ dân",en:"Household subsidy"},value:"240,000,000,000 VND"},{label:{vi:"Lợi ích ròng mỗi năm",en:"Net benefit per year"},value:"85,000,000,000 VND x 4"},{label:{vi:"Suất chiết khấu mô phỏng",en:"Training discount rate"},value:"10%"}]},crisis:{vi:"Phó viện trưởng nhắn: “Lãnh đạo thành phố đã công bố chương trình rồi. Em bỏ kịch bản giá xăng giảm làm NPV âm và gom bớt ý kiến phản đối trong tham vấn đi, báo cáo nộp sáng mai chỉ nên có số đẹp.”",en:"The deputy director texts: “City leaders have already announced the programme. Drop the low fuel price scenario that turns NPV negative and trim the opposing consultation comments, tomorrow's report should only show good numbers.”"},options:{safe:{vi:"Giữ đầy đủ phân tích độ nhạy và ý kiến tham vấn, trình bày rủi ro minh bạch, báo Viện trưởng và đề xuất phương án giảm rủi ro như thí điểm theo giai đoạn.",en:"Keep the full sensitivity analysis and consultation comments, present risks transparently, inform the director and propose risk-reducing options such as a phased pilot."},shortcut:{vi:"Xóa kịch bản bất lợi và ý kiến phản đối để báo cáo đẹp, đúng ý lãnh đạo.",en:"Delete the adverse scenario and opposing comments so the report pleases leadership."},wait:{vi:"Nộp bản nháp như cũ và để Phó viện trưởng tự sửa.",en:"Submit the draft unchanged and let the deputy director edit it."}},questions:{vi:["Vì sao tiền trợ giá là TRANSFER chứ không phải COST trong phân tích kinh tế? Điều đó thay đổi NPV ra sao?","Trình bày cách chiết khấu dòng lợi ích và vì sao phải giữ kịch bản độ nhạy bất lợi trong báo cáo."],en:["Why is the subsidy a TRANSFER rather than a COST in the economic analysis? How does that change the NPV?","Explain how you discounted the benefit stream and why the adverse sensitivity scenario must stay in the report."]},hints:{vi:["Đặt bản nháp cạnh hướng dẫn phân loại dòng tiền và đánh dấu khoản bị xếp sai.","Loại khoản chuyển giao khỏi chi phí năm 0 rồi chiết khấu từng năm theo SOP mục 3.2.","Đọc lại SOP mục 4.2: không được loại bỏ dữ liệu bất lợi hay ý kiến tham vấn để làm đẹp kết quả."],en:["Place the draft next to the cash flow classification guidance and flag the misclassified item.","Remove transfers from the year-0 cost, then discount each year per SOP 3.2.","Re-read SOP 4.2: adverse data and consultation comments must never be removed to polish the results."]}},learning:{summary:{vi:"Chuyên viên phân tích chính sách công xác định vấn đề chính sách, xây dựng các phương án, đánh giá tác động kinh tế, xã hội, môi trường, giới và thủ tục hành chính, rồi khuyến nghị phương án phù hợp cho cơ quan ra quyết định. Nghề đòi hỏi phương pháp định lượng như CBA, CEA, hiểu quy trình xây dựng chính sách, kỹ năng tham vấn và viết báo cáo khách quan, minh bạch về giả định và giới hạn.",en:"A public policy analyst defines policy problems, designs options, assesses economic, social, environmental, gender and administrative impacts and recommends a suitable option to decision makers. The role requires quantitative methods such as CBA and CEA, knowledge of the policy-making process, consultation skills and objective reporting that is transparent about assumptions and limits."},responsibilities:{vi:["Xác định vấn đề, mục tiêu chính sách và các nhóm chịu tác động.","Thiết kế các phương án chính sách, kể cả phương án giữ nguyên hiện trạng làm mốc so sánh.","Thu thập dữ liệu, ước lượng chi phí, lợi ích và phân tích độ nhạy.","Tổ chức tham vấn các bên liên quan và tổng hợp ý kiến trung thực, đầy đủ.","Viết báo cáo đánh giá tác động, khuyến nghị và đề xuất khung giám sát sau ban hành."],en:["Define the problem, policy objectives and affected groups.","Design policy options, including a do-nothing baseline for comparison.","Collect data, estimate costs and benefits and run sensitivity analysis.","Run stakeholder consultations and summarise views truthfully and completely.","Write the impact assessment report with recommendations and a post-adoption monitoring framework."]},competencies:[{name:{vi:"Phân tích chi phí - lợi ích",en:"Cost-benefit analysis"},desc:{vi:"Phân biệt chi phí nguồn lực với khoản chuyển giao, chiết khấu dòng tiền và tính NPV, B/C.",en:"Separate resource costs from transfers, discount cash flows and compute NPV and B/C ratios."}},{name:{vi:"Thiết kế phương án chính sách",en:"Policy option design"},desc:{vi:"Xây dựng các lựa chọn khả thi về công cụ quy định, tài chính, thông tin và so sánh với mốc cơ sở.",en:"Build feasible regulatory, fiscal and information options and compare them with the baseline."}},{name:{vi:"Phân tích dữ liệu & độ nhạy",en:"Data & sensitivity analysis"},desc:{vi:"Kiểm định độ vững của kết quả theo kịch bản, giá trị ngưỡng và độ bất định của giả định.",en:"Test result robustness with scenarios, switching values and assumption uncertainty."}},{name:{vi:"Tham vấn & truyền thông chính sách",en:"Consultation & communication"},desc:{vi:"Lắng nghe các nhóm chịu tác động và trình bày kết quả dễ hiểu cho người ra quyết định.",en:"Listen to affected groups and present findings clearly to decision makers."}},{name:{vi:"Khách quan khoa học",en:"Scientific objectivity"},desc:{vi:"Báo cáo cả kết quả bất lợi, công khai giả định và không điều chỉnh số liệu theo ý muốn.",en:"Report adverse results, disclose assumptions and never bend numbers to a preferred answer."}}],knowledge:{vi:["Quy trình xây dựng chính sách và đánh giá tác động chính sách theo pháp luật hiện hành về ban hành văn bản quy phạm pháp luật.","Nguyên tắc phân tích chi phí - lợi ích kinh tế: chi phí cơ hội, khoản chuyển giao, giá mờ, suất chiết khấu xã hội.","Phân tích chi phí - hiệu quả (CEA) và phân tích đa tiêu chí (MCA) khi lợi ích khó lượng hóa bằng tiền.","Khung đánh giá tác động pháp quy (RIA) và hướng dẫn thực hành tốt của OECD.","Khung theo dõi, đánh giá (M&E) và chuỗi kết quả đầu vào - đầu ra - kết quả - tác động."],en:["Policy-making and policy impact assessment under the current law on promulgating legal documents.","Economic CBA principles: opportunity cost, transfers, shadow prices and the social discount rate.","Cost-effectiveness analysis (CEA) and multi-criteria analysis (MCA) when benefits are hard to monetise.","The regulatory impact assessment (RIA) framework and OECD good practice guidance.","Monitoring and evaluation (M&E) frameworks and the input - output - outcome - impact results chain."]},tools:["Bảng tính mô hình CBA","Ngôn ngữ R hoặc Python","Phần mềm thống kê","Công cụ khảo sát trực tuyến","Bản đồ GIS"],kpis:{vi:["Tỷ lệ báo cáo được hội đồng thẩm định chấp nhận mà không phải làm lại phần phân tích.","Mức độ đầy đủ của giả định, nguồn dữ liệu và phân tích độ nhạy trong báo cáo.","Thời gian hoàn thành đánh giá tác động so với kế hoạch xây dựng văn bản.","Tỷ lệ khuyến nghị được tiếp thu và có chỉ số giám sát sau ban hành."],en:["Share of reports accepted by the appraisal council without reworking the analysis.","Completeness of assumptions, data sources and sensitivity analysis in reports.","Time to complete the impact assessment versus the drafting plan.","Share of recommendations adopted with post-adoption monitoring indicators."]},day:[{time:"08:30",vi:"Rà soát dữ liệu mới từ cơ quan thống kê và khảo sát hộ gia đình.",en:"Review new data from the statistics office and household surveys."},{time:"10:00",vi:"Cập nhật mô hình CBA, kiểm tra phân loại dòng tiền và chiết khấu.",en:"Update the CBA model and check cash flow classification and discounting."},{time:"13:30",vi:"Chủ trì phiên tham vấn với hiệp hội, người dân và doanh nghiệp.",en:"Chair a consultation with associations, residents and businesses."},{time:"15:30",vi:"Chạy phân tích độ nhạy theo giá nhiên liệu và tỷ lệ hộ tham gia.",en:"Run sensitivity analysis on fuel prices and household take-up."},{time:"17:00",vi:"Viết phần khuyến nghị, ghi rõ giả định và giới hạn của phân tích.",en:"Write the recommendations, stating assumptions and limits of the analysis."}],mistakes:{vi:["Tính khoản chuyển giao như trợ giá, thuế vào chi phí kinh tế, làm sai lệch NPV.","Cộng thẳng lợi ích nhiều năm mà không chiết khấu về giá trị hiện tại.","Lược bỏ kịch bản bất lợi hoặc ý kiến phản biện để báo cáo ủng hộ quyết định đã định sẵn."],en:["Counting transfers such as subsidies and taxes as economic costs, distorting the NPV.","Adding multi-year benefits without discounting them to present value.","Removing adverse scenarios or critical comments so the report backs a decision already made."]},career:[{vi:"Trợ lý nghiên cứu chính sách",en:"Policy research assistant"},{vi:"Chuyên viên phân tích chính sách",en:"Policy analyst"},{vi:"Chuyên viên chính, trưởng nhóm đánh giá tác động",en:"Senior analyst, impact assessment lead"},{vi:"Chuyên gia cao cấp, giám đốc nghiên cứu chính sách",en:"Principal expert, director of policy research"}],glossary:[{term:"CBA",vi:"Phân tích chi phí - lợi ích: so sánh toàn bộ chi phí và lợi ích xã hội quy ra tiền của một phương án.",en:"Cost-benefit analysis: comparing all monetised social costs and benefits of an option."},{term:"NPV",vi:"Giá trị hiện tại ròng: tổng lợi ích trừ chi phí sau khi chiết khấu về thời điểm hiện tại.",en:"Net present value: benefits minus costs after discounting to the present."},{term:"Transfer payment",vi:"Khoản chuyển giao như thuế, trợ cấp, chỉ chuyển tiền giữa các nhóm, không tiêu hao nguồn lực thật.",en:"A payment such as a tax or subsidy that moves money between groups without using real resources."},{term:"Sensitivity analysis",vi:"Phân tích kết quả thay đổi thế nào khi giả định quan trọng thay đổi.",en:"Analysis of how results change when key assumptions change."},{term:"RIA",vi:"Đánh giá tác động pháp quy: quy trình phân tích hệ quả của chính sách trước khi ban hành.",en:"Regulatory impact assessment: analysing a policy's consequences before adoption."}],quiz:[{q:{vi:"Lợi ích 110 tỷ đồng nhận sau đúng 1 năm, suất chiết khấu 10%. Giá trị hiện tại là bao nhiêu?",en:"A benefit of 110 billion VND arrives in exactly 1 year at a 10% discount rate. What is its present value?"},options:{vi:["121 tỷ đồng","110 tỷ đồng","99 tỷ đồng","100 tỷ đồng"],en:["121 billion VND","110 billion VND","99 billion VND","100 billion VND"]},answer:3,explain:{vi:"PV = 110 ÷ 1,1 = 100 tỷ đồng.",en:"PV = 110 ÷ 1.1 = 100 billion VND."}},{q:{vi:"Trong CBA kinh tế, thuế và trợ giá giữa Nhà nước và người dân được xử lý thế nào?",en:"In an economic CBA, how are taxes and subsidies between the state and citizens treated?"},options:{vi:["Là khoản chuyển giao, không tính vào chi phí nguồn lực","Luôn tính là chi phí","Luôn tính là lợi ích","Tính gấp đôi để thận trọng"],en:["As transfers, excluded from resource costs","Always as costs","Always as benefits","Counted twice for prudence"]},answer:0,explain:{vi:"Khoản chuyển giao chỉ phân phối lại tiền giữa các nhóm; tính vào chi phí sẽ làm sai lệch kết quả.",en:"Transfers only redistribute money between groups; counting them as costs distorts the result."}},{q:{vi:"Lãnh đạo yêu cầu bỏ kịch bản làm NPV âm trước khi nộp báo cáo. Bạn làm gì?",en:"A leader asks you to drop the scenario that makes NPV negative before submission. What do you do?"},options:{vi:["Xóa kịch bản cho nhanh","Giữ kịch bản, trình bày minh bạch và báo cáo cấp có thẩm quyền","Sửa giả định để NPV dương","Không nộp báo cáo"],en:["Delete it to save time","Keep it, present it transparently and inform the proper authority","Tweak assumptions until NPV is positive","Do not submit the report"]},answer:1,explain:{vi:"Người ra quyết định cần thấy đầy đủ rủi ro; che giấu kết quả bất lợi vi phạm chuẩn mực nghề nghiệp.",en:"Decision makers need the full risk picture; hiding adverse results breaches professional standards."}},{q:{vi:"Khi lợi ích chính là số ca bệnh tránh được và khó quy ra tiền, nên dùng phương pháp nào?",en:"When the main benefit is cases of illness avoided and hard to monetise, which method fits?"},options:{vi:["Phân tích hòa vốn","Phân tích dòng tiền tài chính","Phân tích chi phí - hiệu quả (CEA)","Định giá cổ phiếu"],en:["Break-even analysis","Financial cash flow analysis","Cost-effectiveness analysis (CEA)","Equity valuation"]},answer:2,explain:{vi:"CEA so sánh chi phí trên mỗi đơn vị kết quả như chi phí cho mỗi ca bệnh tránh được.",en:"CEA compares cost per unit of outcome, such as cost per case of illness avoided."}}],tools_en:["CBA model spreadsheet","R or Python","Statistical software","Online survey tools","GIS maps"]}}})})(window.KKR);
